    stat: *const fn (S3StatResult, *anyopaque) JSTerminatedError!void,
    download: *const fn (S3DownloadResult, *anyopaque) JSTerminatedError!void,
    upload: *const fn (S3UploadResult, *anyopaque) JSTerminatedError!void,
    delete: *const fn (S3DeleteResult, *anyopaque) JSTerminatedError!void,
