    part: *const fn (S3PartResult, *anyopaque) JSTerminatedError!void,
    pub fn has(s: []const u8) bool { if (comptime @typeInfo(@This()).@"union".tag_type) |TagType| { return std.meta.stringToEnum(TagType, s) != null; } return false; }
    pub fn name(self: @This()) []const u8 { return @tagName(self); }

pub fn fail(self: S3HttpSimpleTaskCallback, code: []const u8, message: []const u8, context: *anyopaque) JSTerminatedError!void {
            switch (self) {
.upload => |cb| {
_ = try cb(.{ .failure = .{ .code = code, .message = message } }, context);
},
.download => |cb| {
_ = try cb(.{ .failure = .{ .code = code, .message = message } }, context);
},
.stat => |cb| {
_ = try cb(.{ .failure = .{ .code = code, .message = message } }, context);
},
.delete => |cb| {
_ = try cb(.{ .failure = .{ .code = code, .message = message } }, context);
},
.listObjects => |cb| {
_ = try cb(.{ .failure = .{ .code = code, .message = message } }, context);
},
.commit => |cb| {
_ = try cb(.{ .failure = .{ .code = code, .message = message } }, context);
},
.part => |cb| {
_ = try cb(.{ .failure = .{ .code = code, .message = message } }, context);
},
}
    }

pub fn notFound(self: S3HttpSimpleTaskCallback, code: []const u8, message: []const u8, context: *anyopaque) JSTerminatedError!void {
            switch (self) {
.download => |cb| {
_ = try cb(.{ .not_found = .{ .code = code, .message = message } }, context);
},
.stat => |cb| {
_ = try cb(.{ .not_found = .{ .code = code, .message = message } }, context);
},
.delete => |cb| {
_ = try cb(.{ .not_found = .{ .code = code, .message = message } }, context);
},
.listObjects => |cb| {
_ = try cb(.{ .not_found = .{ .code = code, .message = message } }, context);
},
else => {
_ = try self.fail(code, message, context);
},
}
    }
};

