pub fn release(self: *S3HttpSimpleTask) void {
            if (self.result.certificate_info) |certificate| {
                _ = &certificate;
                _ = certificate.deinit(bun.default_allocator);
            }
            _ = self.poll_ref.unref(self.vm);
            _ = self.response_buffer.deinit();
            _ = self.headers.deinit();
            _ = self.sign_result.deinit();
            _ = self.http.clearData();
            if (self.range) |range| {
                _ = &range;
                _ = bun.default_allocator.free(range);
            }
            if ((self.proxy_url.len > 0)) {
                _ = bun.default_allocator.free(self.proxy_url);
            }
            if (self.result.metadata) |*metadata| {
                _ = &metadata;
                _ = (metadata.*).deinit(bun.default_allocator);
            }
    }

pub fn deinit(self: *S3HttpSimpleTask) void {
            _ = self.release();
            _ = bun.destroy(self);
    }

pub fn errorWithBody(self: *S3HttpSimpleTask, comptime error_type: ErrorType) JSTerminatedError!void {
            var code: []const u8 = "UnknownError";
            _ = &code;
            var message: []const u8 = "an unexpected error has occurred";
            _ = &message;
            var has_error_code = false;
            _ = &has_error_code;
            if (self.result.fail) |req_err| {
                _ = &req_err;
                code = @errorName(req_err);
                has_error_code = true;
            } else {
                if (self.result.body) |body| {
                    _ = &body;
                    const bytes: []const u8 = body.list.items;
                    if ((bytes.len > 0)) {
                        message = bytes;
                        if (strings.indexOf(bytes, "<Code>")) |start| {
                            _ = &start;
                            if (strings.indexOf(bytes, "</Code>")) |end| {
                                _ = &end;
                                code = bytes[(start + "<Code>".len)..end];
                                has_error_code = true;
                            }
                        }
                        if (strings.indexOf(bytes, "<Message>")) |start| {
                            _ = &start;
                            if (strings.indexOf(bytes, "</Message>")) |end| {
                                _ = &end;
                                message = bytes[(start + "<Message>".len)..end];
                            }
                        }
                    }
                }
            }
            if ((error_type == .not_found)) {
                if ((!has_error_code)) {
                    code = "NoSuchKey";
                    message = "The specified key does not exist.";
                }
                _ = try self.callback.notFound(code, message, self.callback_context);
            } else {
                _ = try self.callback.fail(code, message, self.callback_context);
            }
    }

pub fn failIfContainsError(self: *S3HttpSimpleTask, status: u32) JSTerminatedError!bool {
            var code: []const u8 = "UnknownError";
            _ = &code;
            var message: []const u8 = "an unexpected error has occurred";
            _ = &message;
            if (self.result.fail) |req_err| {
                _ = &req_err;
                code = @errorName(req_err);
            } else {
                if (self.result.body) |body| {
                    _ = &body;
                    const bytes: []const u8 = body.list.items;
                    var has_error = false;
                    _ = &has_error;
                    if ((bytes.len > 0)) {
                        message = bytes;
                        if ((strings.indexOf(bytes, "<Error>") != null)) {
                            has_error = true;
                            if (strings.indexOf(bytes, "<Code>")) |start| {
                                _ = &start;
                                if (strings.indexOf(bytes, "</Code>")) |end| {
                                    _ = &end;
                                    code = bytes[(start + "<Code>".len)..end];
                                }
                            }
                            if (strings.indexOf(bytes, "<Message>")) |start| {
                                _ = &start;
                                if (strings.indexOf(bytes, "</Message>")) |end| {
                                    _ = &end;
                                    message = bytes[(start + "<Message>".len)..end];
                                }
                            }
                        }
                    }
                    if ((((!has_error) and (status == 200)) or (status == 206))) {
                        return false;
                    }
                } else {
                    if (((status == 200) or (status == 206))) {
                        return false;
                    }
                }
            }
            _ = try self.callback.fail(code, message, self.callback_context);
            return true;
    }

